              className="space-y-1 border-b pb-6 last:border-0"
            >
              <p className="text-sm text-muted-foreground">{item.label}</p>
              <p
                dir={item.dir}
                className={
                  item.dir === "ltr"
                    ? "font-medium tracking-normal [letter-spacing:0]"
                    : "font-medium"
                }
              >
                {item.value}
              </p>
            </li>
          ))}
        </ul>
      </section>
    </div>
  )
}

