          aria-label="سه رقم"
          inputMode="numeric"
          autoComplete="off"
          disabled={disabled}
          value={toFaDigits(plate.middle)}
          placeholder="۳۴۵"
          onChange={(event) => onDigits("middle", event.target.value, "region")}
          onKeyDown={(event) => onDigitsKey(event, "middle", "letter")}
          onFocus={(event) => event.target.select()}
          className={cn(digitBox, "w-16")}
