    if (event.key === "Backspace") {
      event.preventDefault()
      if (plate.letter) commit({ ...plate, letter: "" })
      else focus("left")
      return
    }
    if (
      event.key === "Enter" ||
      event.key === " " ||
      event.key === "ArrowDown" ||
      event.key === "ArrowUp"
    ) {
      event.preventDefault()
      openList()
      return
    }
    if (event.key.length === 1) {
      const letter = plateLetterFromKey(event.key)
      if (letter && allowed.has(letter)) {
        event.preventDefault()
        chooseLetter(letter)
      }
