      case "ArrowLeft":
        return move(active + 1)
      case "ArrowRight":
        return move(active - 1)
      case "ArrowDown":
        return move(active + COLS)
      case "ArrowUp":
        return move(active - COLS)
      case "Home":
        return move(0)
      case "End":
        return move(total - 1)
      case "Enter":
      case " ":
        event.preventDefault()
        return chooseLetter(options[active].letter)
      case "Escape":
        event.preventDefault()
        setOpen(false)
        return focus("letter")
      case "Tab":
        return setOpen(false)
      default: {
        const letter =
          event.key.length === 1 ? plateLetterFromKey(event.key) : null
        if (letter && allowed.has(letter)) {
          event.preventDefault()
          chooseLetter(letter)
        }
      }
    }
  }

  React.useEffect(() => {
    if (!open) return
    const onDoc = (event: MouseEvent) => {
      const target = event.target as Node
      if (root.current?.contains(target) || panel.current?.contains(target)) {
        return
      }
      setOpen(false)
    }
    document.addEventListener("mousedown", onDoc)
    return () => document.removeEventListener("mousedown", onDoc)
  }, [open])

  React.useEffect(() => {
    if (open) optionRefs.current[active]?.focus()
  }, [open, active])

  React.useLayoutEffect(() => {
    if (!open || !root.current) return
    const update = () => {
      const rect = root.current!.getBoundingClientRect()
      const width = 260
      const left = Math.min(
        Math.max(8, rect.left + rect.width / 2 - width / 2),
        window.innerWidth - width - 8
      )
      setPanelStyle({
        position: "fixed",
        top: rect.bottom + 8,
        left,
        width,
        zIndex: 80,
      })
    }
    update()
    window.addEventListener("resize", update)
    window.addEventListener("scroll", update, true)
    return () => {
