            <Input
              type="text"
              placeholder="نام شما"
              dir="rtl"
              className="sm:flex-1"
            />
            <Input
              type="email"
              required
              placeholder="name@example.com"
              dir="ltr"
              className="text-start sm:flex-1"
            />
            <Button type="submit" className="sm:shrink-0">
              عضویت
            </Button>
          </form>
        </CardContent>
      </Card>
    </section>
  )
}

