            <ChevronLeftIcon />
          </Button>
          <Button size="sm">افزودن</Button>
        </div>
      </div>

      <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-4 xl:grid-cols-7">
        {days.map((day, idx) => {
          const isToday = day.toDateString() === todayKey
          const events = WEEK_EVENTS[idx] ?? []
          return (
            <Card
              key={day.toISOString()}
              className={
                isToday ? "border-primary/40 ring-1 ring-primary/20" : undefined
              }
            >
              <CardHeader className="pb-2 text-start">
                <div className="flex items-start justify-between gap-1">
                  <div>
                    <CardDescription>
                      {formatJalaliDayName(day)}
                    </CardDescription>
                    <CardTitle className="text-lg tracking-normal">
                      {formatJalaliDay(day)}
                    </CardTitle>
                  </div>
                  {isToday ? <Badge>امروز</Badge> : null}
                </div>
              </CardHeader>
              <CardContent className="space-y-2">
                {events.length === 0 ? (
                  <p className="text-xs text-muted-foreground">بدون برنامه</p>
                ) : (
                  events.map((ev) => {
                    const key = `${idx}-${ev.time}-${ev.title}`
                    return (
                      <div
                        key={key}
                        className="rounded-md border bg-muted/30 px-2 py-1.5 text-xs"
                      >
                        <div className="flex items-center justify-between gap-1">
                          <Badge variant="outline" className="text-[10px]">
                            {ev.type}
                          </Badge>
                          <Popover
                            open={openKey === key}
                            onOpenChange={(open) =>
                              setOpenKey(open ? key : null)
                            }
                          >
                            <PopoverTrigger
                              render={
                                <Button
                                  type="button"
                                  variant="ghost"
                                  size="icon-xs"
                                  aria-label="عملیات"
                                />
                              }
                            >
                              <MoreHorizontalIcon />
                            </PopoverTrigger>
                            <PopoverContent
                              dir="rtl"
                              lang="fa"
                              align="start"
                              className="w-32 p-1"
                            >
                              <Button
                                type="button"
                                variant="ghost"
                                size="sm"
                                className="w-full justify-start"
                                onClick={() => setOpenKey(null)}
                              >
                                ویرایش
                              </Button>
                              <Button
                                type="button"
                                variant="ghost"
                                size="sm"
                                className="w-full justify-start text-destructive"
                                onClick={() => setOpenKey(null)}
                              >
                                حذف
                              </Button>
                            </PopoverContent>
                          </Popover>
                        </div>
                        <p className="mt-1 font-medium">{ev.title}</p>
                        <p className="tracking-normal text-muted-foreground">
                          {ev.time}
                        </p>
                      </div>
                    )
                  })
                )}
              </CardContent>
            </Card>
          )
        })}
      </div>

      <Separator className="my-6" />
      <p className="text-center text-xs text-muted-foreground">
        هفته از شنبه تا جمعه · تاریخ‌ها شمسی
      </p>
    </section>
  )
}

